// Build the agent's system prompt as an array of content blocks:
//   - Block 0: the stable skill content (AGENTS.md + SKILL.md files), cached
//     via Anthropic prompt caching. Same content across requests.
//   - Block 1 (optional): per-request pending-proposal context — every card
//     waiting in the thread. NOT cached, since it varies per Slack thread +
//     per request.
//
// The harness is baked into the Worker bundle at build time (see
// src/generated/harness.ts, generated by scripts/bundle-harness.mjs) so serving
// it costs ZERO subrequests — it updates on deploy. This replaced the old
// runtime GitHub-Raw fetch (~20 subrequests) that blew the free-tier cap.

import type { Env } from "../types";
import { HARNESS } from "../generated/harness";
import { proposalOperations, type PendingProposal } from "../thread-state/index";
import { CARD_WINDOW_WORDS } from "../card-expiry";
import { cardHeadline, cardTargets } from "./card-identity";
import { REVISES_CARD } from "./tool-table";

/** One card waiting in the thread, as the model is shown it. */
export interface PendingContext {
  /** The card's id — its message ts — which a gated call names in
   *  `revises_card` to revise it (`agent/tool-table.ts`). */
  id: string;
  /** What a person would call it (`card-identity.ts`). */
  headline: string;
  /** The Notion pages and GitHub issues it writes, if it names any. */
  targets: string[];
  /** The whole staged batch. The model has to see every operation it is being
   *  asked about — one ✅ resolves all of them, so a context showing only the
   *  first would have it confirm three writes it never read. And a revision is
   *  built from it: the new card carries what the old one held. */
  operations: Array<{ toolName: string; input: Record<string, unknown> }>;
  toolName: string;
  input: Record<string, unknown>;
  requesterUserId: string;
}

/** A live card, as its pending-proposal context entry. */
export function pendingContextOf(card: PendingProposal): PendingContext {
  return {
    id: card.proposalTs,
    headline: cardHeadline(card),
    targets: cardTargets(card),
    operations: proposalOperations(card),
    toolName: card.toolName,
    input: card.input,
    requesterUserId: card.requesterUserId,
  };
}

export interface SenderContext {
  userId: string;
}

export interface SystemBlock {
  type: "text";
  text: string;
  cache_control?: { type: "ephemeral"; ttl?: "5m" | "1h" };
}

// The harness is baked into the bundle, so serving it is a synchronous constant
// read — zero subrequests, no cache/KV/fetch. It updates on deploy.
// env is unused now but kept for signature stability with existing callers.
function getStableSystem(_env: Env): string {
  return HARNESS;
}

export async function buildSystemBlocks(
  env: Env,
  pending: readonly PendingContext[] | null,
  sender: SenderContext | null,
  assistantContext?: string | null,
): Promise<SystemBlock[]> {
  const stable = getStableSystem(env);
  // NB: only the Claude adapter honors this. The Gemini adapter flattens these
  // blocks into one `systemInstruction` string and the Gemini API has no
  // cache_control, so on the PRODUCTION provider the harness rides uncached on
  // every iteration unless Google's implicit caching picks up the stable prefix.
  // providers/gemini.ts logs `cached_in=` so that is measured, not assumed.
  //
  // 1h cache TTL on the stable block: design-team traffic gaps blow the 5-min
  // cache TTL; 1h costs 2× on write, pays back on the first reuse within the
  // hour. (ttl is post-SDK-0.32 — SystemBlock carries it; the API accepts it.)
  const blocks: SystemBlock[] = [
    { type: "text", text: stable, cache_control: { type: "ephemeral", ttl: "1h" } },
  ];
  // Per-request, uncached (after the cached stable block so the cache prefix
  // stays stable): who sent the current message. Without this the model knows
  // the whole team roster (harness) but NOT who it's talking to — and a weaker
  // model will guess a roster name for the person speaking ("Hi Meryem!" to
  // Bill, live incident 2026-07-16 on the gemini-2.5-pro backup model).
  if (sender && SLACK_USER_ID.test(sender.userId)) {
    blocks.push({ type: "text", text: renderSenderBlock(sender.userId) });
  }
  // Per-request, uncached (varies per thread): what the user has open in the
  // assistant panel. Advisory only — the prompt tells the model not to
  // over-index on it.
  if (assistantContext) {
    blocks.push({ type: "text", text: renderAssistantContextBlock(assistantContext) });
  }
  if (pending?.length) {
    blocks.push({ type: "text", text: renderPendingBlock(pending, sender) });
  }
  return blocks;
}

// Same validation discipline as the panel-context channel id: this string
// lands in a system block, so only a shape-checked Slack user id may pass.
const SLACK_USER_ID = /^[UW][A-Z0-9]{2,20}$/;

function renderSenderBlock(userId: string): string {
  return [
    "<current_sender>",
    `The current message was sent by <@${userId}>.`,
    "Addressing policy (strict, 2026-07-16 after a misaddressed-greeting incident):",
    `- Default: do NOT address the person by any name — "Hey!" beats "Hey <name>!".`,
    `- If addressing them is genuinely needed (e.g. disambiguating between thread participants), use EXACTLY the mention token <@${userId}> and nothing else — Slack renders it as their correct name. Never a plain-text name.`,
    "- You do NOT otherwise know who is speaking. The team-roster names in your instructions are routing candidates (\"who should I ask about X\"), never the identity of the person in this conversation.",
    "</current_sender>",
  ].join("\n");
}

function renderAssistantContextBlock(ctx: string): string {
  return [
    "<assistant_panel_context>",
    `The user is chatting from the assistant panel and currently has this open: ${ctx}.`,
    // Deictic examples must map to real tool paths: "who's in here" →
    // slack_channel_members, "this channel" → disambiguation only. "What's
    // happening here" was cut — no tool reads a channel's recent history yet.
    'Use this ONLY to disambiguate a vague, deictic ask ("this channel", "who\'s in here") — never assume it is the subject of a specific question. When in doubt, answer the words, not the panel.',
    "</assistant_panel_context>",
  ].join("\n");
}

/** One waiting card's entry: its number, id and headline, what it writes,
 *  and its whole staged batch. */
function renderPendingCard(p: PendingContext, n: number): string[] {
  return [
    `Card ${n} — id \`${p.id}\` — "${p.headline}"`,
    ...(p.targets.length ? [`- writes: ${p.targets.join(", ")}`] : []),
    // A batch reads as a numbered list; a single operation reads exactly as it
    // always has, which is what the overwhelming majority of proposals are.
    ...(p.operations.length > 1
      ? [
          `- operations (${p.operations.length}, all resolved together):`,
          ...p.operations.map(
            (op, i) => `  ${i + 1}. ${op.toolName} — ${JSON.stringify(op.input)}`,
          ),
        ]
      : [`- tool: ${p.toolName}`, `- parameters: ${JSON.stringify(p.input, null, 2)}`]),
    // A card the Worker staged itself (a weekly DS precedence card) has no requester.
    p.requesterUserId ? `- requester: <@${p.requesterUserId}>` : "- requester: none — uno-bot staged this card itself",
  ];
}

/**
 * Every card waiting in the thread, newest first, and how to read the
 * current message against them (#1318): a decision on a card resolves it, a
 * change to one is a revision naming it, a different matter is a separate
 * proposal beside them. Exported for the turn harness, which shows its scripted
 * model the same block.
 */
export function renderPendingBlock(cards: readonly PendingContext[], sender: SenderContext | null): string {
  const several = cards.length > 1;
  return [
    "<pending_proposal>",
    several
      ? `These ${cards.length} proposal cards are waiting for a decision in this Slack thread, newest first:`
      : "You previously proposed a side-effect action in this Slack thread that is awaiting confirmation:",
    ...cards.flatMap((card, i) => ["", ...renderPendingCard(card, i + 1)]),
    sender ? `\nCurrent message sender: <@${sender.userId}>` : "",
    "",
    "Read the user's current message against these cards:",
    `- A decision on a card: if it says yes in any words — "go ahead", "sure", "ok", "sounds good", "yep do it" — invoke \`proposal_resolve\` with decision "confirm"; if it says no, cancel.${several ? " Set `card` to the id of the card it decides. If the message does not say which card, do not guess: call `proposal_resolve` without `card` and end your turn — they are asked which: the question offers Approve… for one card and Cancel… for any, and each card's own Review approves it too." : ""}`,
    `- A change to a waiting card (an edit, "make the title shorter", a reply about that card): call that card's tool again with its whole input, the change applied, and \`${REVISES_CARD}\` set to the card's id. The new card replaces it and keeps everything else it held.${several ? " If it is unclear which card the change means, ask which, naming them." : ""}`,
    `- A request for a different matter: call its tool without \`${REVISES_CARD}\`. It posts as a separate card beside the waiting ones, and each is decided on its own, in any order. Something that builds on a waiting card is the same matter: revise that card instead.`,
    `- Anything else: reply conversationally; the proposal sits until someone presses ✅ / ⛔ on the card, reacts, or it expires ${CARD_WINDOW_WORDS} after it was staged — Saturday and Sunday do not count.`,
    "",
    "A new card that writes the same Notion page or GitHub issue as a waiting card always replaces it — the Worker treats it as a revision of that card. Re-invoking a card's tool with identical parameters confirms that card rather than posting a second one.",
    "",
    "Authorization: anyone in the thread may confirm or cancel — not just the original requester. A clear go-ahead/cancel from any participant resolves it.",
    "</pending_proposal>",
  ].filter(Boolean).join("\n");
}

